async function refresh(){let me=await api('/me');if(me.user.role==='vendor')return;let [v,o,c]=await Promise.all([api('/state'),api('/orders'),api('/customers')]);setData(v);setOrders(o.orders);setCustomers(c.customers);if(me.user.role==='admin'){let feed=await api('/admin/activity');setActivities(feed.events)}}
useEffect(()=>{(async()=>{try{let setup=await api('/setup/status');if(!setup.setup){setSetupAvailable(true);setMode(portal==='admin'?'setup':'login');setError(portal==='admin'?'':'First create the store owner account at /admin.');return}setSetupAvailable(false);let me=await api('/me');if(me.user.role!==portal){setMode('login');setError('This account belongs to the '+me.user.role+' panel. Open /'+me.user.role+' instead.');return}setUser(me.user.name);setRole(me.user.role);setView(me.user.role==='staff'?'pos':'dashboard');await refresh();setMode('ready')}catch(e){setMode(e.message.includes('sign in')?'login':'error');setError(e.message)}})()},[]);
async function sign(e){e.preventDefault();setError('');try{setBusy(true);if(mode==='setup'){await api('/setup','POST',{name:owner,password});setSetupAvailable(false);let r=await api('/login','POST',{password});setUser(r.name);setRole('admin');await refresh();setMode('ready');setPassword('');flash('Store owner account created.')}else{if(portal!=='admin'&&!email)throw Error('Enter your '+portal+' account email.');let r=await api(portal==='admin'?'/login':'/account/login','POST',portal==='admin'?{password}:{email,password});if((r.role||'admin')!==portal){await api('/logout','POST');throw Error('This account belongs to the '+r.role+' panel. Open /'+r.role+' instead.')}setUser(r.name);setRole(r.role||'admin');setView(r.role==='staff'?'pos':'dashboard');await refresh();setMode('ready');setPassword('')}}catch(e){setError(e.message)}finally{setBusy(false)}}
async function handleFirebaseIdentity(identity,link=false){if(portal!=='admin')throw Error('Google/mobile sign-in is for linked store owners only.');let token=await identity.getIdToken(),r=await fetch('/api/admin/'+(link?'link':'firebase-login'),{method:'POST',credentials:'same-origin',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:'{}'}),j=await r.json();if(!r.ok)throw Error(j.error||'Sign-in failed');if(link){setLinkOpen(false);flash('Verified account linked for admin sign-in.')}else{setUser(j.name);setRole('admin');await refresh();setMode('ready');flash('Signed in securely.')}}
async function adminGoogle(link=false){if(!firebaseConfigured){setError('Configure Firebase before enabling Google sign-in.');return}setError('');try{setBusy(true);let result=await signInWithPopup(firebaseAuth,new GoogleAuthProvider());await handleFirebaseIdentity(result.user,link)}catch(e){setError(e.message)}finally{setBusy(false)}}
async function adminPhoneSend(){setError('');try{if(!/^\+[1-9]\d{7,14}$/.test(adminPhone))throw Error('Use a number with country code, e.g. +923001234567');setBusy(true);adminVerifier.current ||= new RecaptchaVerifier(firebaseAuth,'admin-recaptcha',{size:'normal'});setAdminPhoneResult(await signInWithPhoneNumber(firebaseAuth,adminPhone,adminVerifier.current));flash('Verification code sent.')}catch(e){setError(e.message);adminVerifier.current?.clear();adminVerifier.current=null}finally{setBusy(false)}}
async function adminPhoneVerify(link=false){setError('');try{setBusy(true);let result=await adminPhoneResult.confirm(adminCode);await handleFirebaseIdentity(result.user,link);setAdminPhoneResult(null);setAdminCode('')}catch(e){setError(e.message)}finally{setBusy(false)}}
async function loadAccounts(){let r=await api('/accounts');setAccounts(r.accounts)}
async function uploadPicture(productId,file){if(!file)return;setBusy(true);setError('');try{let img=await createImageBitmap(file),scale=Math.min(1,900/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.82));img.close();if(blob.size>1_000_000)throw Error('Image is too large after resizing');let r=await fetch('/api/products/'+productId+'/image',{method:'POST',body:blob,credentials:'same-origin'}),j=await r.json();if(!r.ok)throw Error(j.error||'Upload failed');await refresh();flash('Product image uploaded.')}catch(e){setError(e.message)}finally{setBusy(false)}}
async function logout(){try{await api('/logout','POST');setMode('login');setRole('admin');setData(blank);setCart({})}catch(e){setError('Could not sign out. '+e.message)}}
async function action(path,method,payload,onDone){setBusy(true);setError('');try{let result=await api(path,method,payload);await refresh();onDone?.(result);flash('Saved successfully.');return result}catch(e){setError(e.message);return null}finally{setBusy(false)}}
const product=id=>data.products.find(p=>p.id===id), stock=p=>Number(p.stock_milli||0), inStock=data.products.filter(p=>!p.deleted_at&&stock(p)>0&&p.catalog_status!=='archived'), low=data.products.filter(p=>!p.deleted_at&&stock(p)<=Number(p.reorder_milli||0));
function receiveStock(p,vendorId=''){setError('');setModal('purchase');setForm({...model.purchase,payment:'Unpaid',productId:p?.id||'',vendorId:p?.vendor_id||vendorId,cost:p?Number(p.cost_paisa)/100:0})}
function open(type,item){setError('');setModal(type);let v=item||model[type]||{};setForm(item?{...v,opening:0,cost:Number(item.cost_paisa)/100,price:Number(item.price_paisa)/100,reorder:Number(item.reorder_milli)/1000,reorderQty:Number(item.reorder_qty_milli)/1000,taxRate:Number(item.tax_rate_bps)/100,packSize:item.pack_size,vendorId:item.vendor_id||'',taxId:item.tax_id||''}:v)}
async function submit(e){e.preventDefault();let type=modal,path={product:'/products',vendor:'/vendors',purchase:'/purchases',adjustment:'/adjustments',expense:'/expenses'}[type],id=form.id;if(id&&(type==='product'||type==='vendor'))path+='/'+id;let result=await action(path,id?'PUT':'POST',form,()=>setModal(null));if(result&&type==='purchase')setView('purchases')}
async function orderAction(id,status,payload){return action('/orders/'+encodeURIComponent(id)+'/'+status,'POST',payload)}
function go(v){setCamera(false);setView(v);setQuery('');setFilter('all');setSidebar(false);setError('');if(v==='accounts'||v==='vendors')loadAccounts().catch(e=>setError(e.message));if(v==='pos')setTimeout(()=>scanRef.current?.focus(),80)}
function add(p){if(p?.deleted_at||p?.catalog_status==='archived'){setError('This product is archived or removed. Restore it before selling.');return}if(!p){setError('Barcode / SKU not found. Add this product in inventory first.');return}let next=Number(cart[p.id]||0)+1000;if(next>stock(p)){setError(p.name+' has only '+Q(stock(p))+' in stock.');return}setCart({...cart,[p.id]:next});setError('');setScan('');scanRef.current?.focus()}
function scanAdd(text=scan){let q=text.trim().toLowerCase();if(!q)return;let p=data.products.find(x=>x.barcode?.toLowerCase()===q||x.sku?.toLowerCase()===q);if(!p){let hits=data.products.filter(x=>x.name.toLowerCase().includes(q));if(hits.length===1)p=hits[0]}add(p)}
function updateCart(id,delta){let next=Number(cart[id]||0)+delta,p=product(id);if(next>stock(p)){setError('Not enough stock for '+p.name);return}let c={...cart};if(next<=0)delete c[id];else c[id]=next;setCart(c);setError('')}
let lines=Object.entries(cart).map(([id,qty])=>({p:product(id),qty})).filter(x=>x.p),subtotal=lines.reduce((a,x)=>a+Math.round(x.qty*Number(x.p.price_paisa)/1000),0),discount=Math.round(Number(bill.discount||0)*100),tax=Math.round(Number(bill.tax||0)*100),loyaltyDiscount=Number(bill.redeemPoints||0)/100*5000,total=Math.max(0,subtotal-discount-loyaltyDiscount+tax);
async function loadCustomer(customerId){if(!customerId){setCustomerInfo(null);return}try{setCustomerInfo(await api('/customers/'+encodeURIComponent(customerId)+'/overview'))}catch(e){setError(e.message)}}
async function checkout(){let payload={lines:lines.map(x=>({productId:x.p.id,qty:x.qty/1000})),...bill};let r=await action('/checkout','POST',payload,()=>{setCart({});setBill({payment:'Cash',discount:0,tax:0,customer:'',customerId:'',redeemPoints:0,received:'',note:''})});if(r){setReceipt(r);if(payload.customerId)await loadCustomer(payload.customerId)}}
function printReceipt(r=receipt){let popup=window.open('','_blank','width=430,height=700');if(!popup){flash('Allow popups to print receipt.');return}let esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));popup.document.write(`<!doctype html><html><head><title>Star Mart ${esc(r.receipt)}</title><style>body{font:14px Arial;width:320px;margin:25px auto;color:#222}h1{text-align:center;color:#fc2600;margin-bottom:0}.sub{text-align:center;letter-spacing:2px;font-size:11px}table{width:100%;border-collapse:collapse;margin:20px 0}td{padding:9px 0;border-bottom:1px dashed #ccc}.row{display:flex;justify-content:space-between;padding:5px 0}.total{font-weight:bold;font-size:18px;border-top:2px solid;margin-top:12px;padding-top:12px}</style></head><body><h1>★ Star Mart</h1><div class="sub">HOUSE OF GROCERIES</div><p>${esc(r.receipt)}<br>${esc(date(r.createdAt))}<br>${esc(r.customer)} · ${esc(r.payment)}</p><table>${r.lines.map(x=>`<tr><td>${esc(x.name)}<br>${Q(x.qty)} × ${M(x.unitPrice)}</td><td align="right">${M(x.total)}</td></tr>`).join('')}</table><div class="row"><span>Subtotal</span><b>${M(r.subtotal)}</b></div><div class="row"><span>Discount</span><b>− ${M(r.discount)}</b></div><div class="row"><span>Tax</span><b>${M(r.tax)}</b></div><div class="row total"><span>Total</span><b>${M(r.total)}</b></div><div class="row"><span>Received</span><b>${M(r.received)}</b></div><div class="row"><span>Change</span><b>${M(Math.max(0,Number(r.received)-Number(r.total)))}</b></div><p style="text-align:center;margin-top:25px">Thank you for shopping!</p></body></html>`);popup.document.close();setTimeout(()=>popup.print(),250)}
function startCamera(){setCamera(true)}
function stopCamera(){setCamera(false)}
async function uploadLegacy(e){let file=e.target.files?.[0];e.target.value='';if(!file)return;setError('');try{let old=JSON.parse(await file.text());setLegacyImport({data:old,name:file.name})}catch(ex){setError('Could not read this backup. Select a valid Star Mart JSON file.')}}
